--
-- Table structure for table `orders`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `order_id` int NOT NULL AUTO_INCREMENT,
  `customer_id` int NOT NULL,
  `restaurant_id` int NOT NULL,
  `rider_id` int DEFAULT NULL,
  `order_type` varchar(20) NOT NULL,
  `delivery_type` varchar(20) NOT NULL,
  `order_status` varchar(20) NOT NULL DEFAULT 'placed',
  `order_timestamp` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`order_id`),
  KEY `fk_orders_user` (`customer_id`),
  KEY `fk_orders_rest` (`restaurant_id`),
  KEY `fk_orders_rider` (`rider_id`),
  CONSTRAINT `fk_orders_rest` FOREIGN KEY (`restaurant_id`) REFERENCES `restaurants` (`restaurant_id`),
  CONSTRAINT `fk_orders_rider` FOREIGN KEY (`rider_id`) REFERENCES `riders` (`rider_id`),
  CONSTRAINT `fk_orders_user` FOREIGN KEY (`customer_id`) REFERENCES `users` (`user_id`),
  CONSTRAINT `chk_dispatch_needs_rider` CHECK (((`order_type` = _utf8mb4'pick-up') or (`order_status` in (_utf8mb4'placed',_utf8mb4'preparing',_utf8mb4'cancelled')) or (`rider_id` is not null))),
  CONSTRAINT `chk_pickup_no_rider` CHECK (((`order_type` = _utf8mb4'delivery') or (`rider_id` is null))),
  CONSTRAINT `orders_chk_1` CHECK ((`order_type` in (_utf8mb4'delivery',_utf8mb4'pick-up'))),
  CONSTRAINT `orders_chk_2` CHECK ((`delivery_type` in (_utf8mb4'standard',_utf8mb4'speedy'))),
  CONSTRAINT `orders_chk_3` CHECK ((`order_status` in (_utf8mb4'placed',_utf8mb4'preparing',_utf8mb4'out for delivery',_utf8mb4'delivered',_utf8mb4'cancelled')))
) ENGINE=InnoDB AUTO_INCREMENT=1001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

